        when(constraintObj.getOwnPropertyNames()).thenReturn(props);
        when(constraintObj.getPropertyType("prop1")).thenReturn(propType);

        PrototypeObjectType spyTarget = spy(targetObj);
        doReturn(false).when(spyTarget).isPropertyTypeDeclared("prop1");
        doReturn(true).when(spyTarget).hasProperty("prop1");

        spyTarget.matchConstraint(constraintObj);

        // Should define the property using the existing propType
        verify(spyTarget).defineInferredProperty("prop1", propType, null);
    }

